package dev.cosmerearcanists.power;
import java.util.*;
import com.mojang.authlib.GameProfile;
import dev.cosmerearcanists.CosmereArcanists;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.material.*;
import net.minecraft.world.ticks.*;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class BubbleWorldGameTests {
    private static FakePlayer caster(GameTestHelper h,String metal){var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"WorldBubble"));p.setPos(net.minecraft.world.phys.Vec3.atCenterOf(h.absolutePos(new BlockPos(1,20,1))));PowerAttributes.set(p,"a:"+metal,1);PowerData.state(p,"a:"+metal,2);PowerData.reserve(p,metal,300);PowerData.assignSlot(p,"a:"+metal,0);PowerService.control(p,new PowerNetwork.Control(2,"",1));BubbleService.create(p,metal);return p;}
    private static <T> LevelTicks<T> queue(ServerLevel level,BlockPos pos){var ticks=new LevelTicks<T>(l->true,level::getProfiler);ticks.addContainer(new ChunkPos(pos),new LevelChunkTicks<>());return ticks;}
    private static <T> void put(LevelTicks<T> queue,T type,BlockPos pos,long due,TickPriority priority,long order){queue.schedule(new ScheduledTick<>(type,pos,due,priority,order));}
    @GameTest(template="empty") public static void scheduledBlocksSlowAndResumeWithTheirRemainingDelay(GameTestHelper h){var p=caster(h,"bendalloy");var pos=p.blockPosition();var queue=BubbleWorldGameTests.<Block>queue(h.getLevel(),pos);long start=h.getLevel().getGameTime();int[] count={0};try{put(queue,Blocks.STONE,pos,start+20,TickPriority.NORMAL,0);for(int i=1;i<=10;i++)BubbleWorldService.tickQueue(h.getLevel(),queue,start+i,100,(at,type)->count[0]++);h.assertTrue(count[0]==0&&queue.hasScheduledTick(pos,Blocks.STONE),"Slow bubble retains the pending tick");PowerService.control(p,new PowerNetwork.Control(2,"",0));for(int i=11;i<25;i++)BubbleWorldService.tickQueue(h.getLevel(),queue,start+i,100,(at,type)->count[0]++);h.assertTrue(count[0]==0,"Collapse does not execute the remaining delay early");BubbleWorldService.tickQueue(h.getLevel(),queue,start+25,100,(at,type)->count[0]++);h.assertTrue(count[0]==1&&!queue.hasScheduledTick(pos,Blocks.STONE),"Ten half-speed frames followed by fifteen normal frames complete exactly once");}finally{BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void scheduledBlocksAccelerateIncludingPreviouslyQueuedTicks(GameTestHelper h){var p=caster(h,"cadmium");var pos=p.blockPosition();var queue=BubbleWorldGameTests.<Block>queue(h.getLevel(),pos);long start=h.getLevel().getGameTime();int[] count={0};try{put(queue,Blocks.STONE,pos,start+20,TickPriority.NORMAL,0);for(int i=1;i<10;i++)BubbleWorldService.tickQueue(h.getLevel(),queue,start+i,100,(at,type)->count[0]++);h.assertTrue(count[0]==0,"Future tick does not execute before ten double-speed frames");BubbleWorldService.tickQueue(h.getLevel(),queue,start+10,100,(at,type)->count[0]++);h.assertTrue(count[0]==1&&!queue.hasScheduledTick(pos,Blocks.STONE),"A previously queued twenty-tick delay completes in ten frames and clears the uniqueness set");}finally{BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void shortScheduledChainsCanAdvanceMoreThanOncePerWorldTick(GameTestHelper h){var p=caster(h,"cadmium");var pos=p.blockPosition();var queue=BubbleWorldGameTests.<Block>queue(h.getLevel(),pos);long start=h.getLevel().getGameTime();int[] count={0};try{put(queue,Blocks.STONE,pos,start+1,TickPriority.NORMAL,0);for(int frame=1;frame<=3;frame++){long now=start+frame;BubbleWorldService.tickQueue(h.getLevel(),queue,now,100,(at,type)->{count[0]++;put(queue,type,at,now+1,TickPriority.NORMAL,count[0]);});}h.assertTrue(count[0]==6,"A one-tick scheduled chain runs twice per real frame in cadmium");}finally{BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void fluidQueuesUseTheSameLocalTimeWithoutChangingOutsideTicks(GameTestHelper h){var p=caster(h,"cadmium");var inside=p.blockPosition();var outside=inside.offset(10,0,0);var queue=BubbleWorldGameTests.<Fluid>queue(h.getLevel(),inside);if(!new ChunkPos(inside).equals(new ChunkPos(outside)))queue.addContainer(new ChunkPos(outside),new LevelChunkTicks<>());long start=h.getLevel().getGameTime();var fired=new ArrayList<BlockPos>();try{put(queue,Fluids.WATER,inside,start+4,TickPriority.NORMAL,0);put(queue,Fluids.WATER,outside,start+4,TickPriority.NORMAL,1);for(int i=1;i<=2;i++)BubbleWorldService.tickQueue(h.getLevel(),queue,start+i,100,(at,type)->fired.add(at));h.assertTrue(fired.equals(List.of(inside)),"Inside water advances twice as fast; outside water retains its deadline");for(int i=3;i<=4;i++)BubbleWorldService.tickQueue(h.getLevel(),queue,start+i,100,(at,type)->fired.add(at));h.assertTrue(fired.equals(List.of(inside,outside)),"Outside pending fluid tick is neither lost nor accelerated");}finally{BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void actualRedstoneLampUsesAcceleratedScheduledTick(GameTestHelper h){var p=caster(h,"cadmium");var pos=p.blockPosition();var level=h.getLevel();var queue=BubbleWorldGameTests.<Block>queue(level,pos);long start=level.getGameTime();try{level.setBlockAndUpdate(pos,Blocks.REDSTONE_LAMP.defaultBlockState().setValue(RedstoneLampBlock.LIT,true));put(queue,Blocks.REDSTONE_LAMP,pos,start+4,TickPriority.NORMAL,0);BubbleWorldService.tickQueue(level,queue,start+1,100,(at,type)->level.getBlockState(at).tick(level,at,level.getRandom()));h.assertTrue(level.getBlockState(pos).getValue(RedstoneLampBlock.LIT),"Lamp retains its lit state before its local delay");BubbleWorldService.tickQueue(level,queue,start+2,100,(at,type)->level.getBlockState(at).tick(level,at,level.getRandom()));h.assertTrue(!level.getBlockState(pos).getValue(RedstoneLampBlock.LIT),"Native four-tick lamp turn-off runs after two accelerated frames");}finally{level.setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void cropRandomTicksUseFreshStatesForEachAcceleratedStep(GameTestHelper h){var p=caster(h,"cadmium");var pos=p.blockPosition();var level=h.getLevel();try{level.setBlockAndUpdate(pos.below(),Blocks.SAND.defaultBlockState());level.setBlockAndUpdate(pos,Blocks.CACTUS.defaultBlockState());level.getBlockState(pos).randomTick(level,pos,level.getRandom());h.assertTrue(level.getBlockState(pos).getValue(CactusBlock.AGE)==2,"One selected random update advances two native cactus growth steps with fresh block states");}finally{level.setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());level.setBlockAndUpdate(pos.below(),Blocks.AIR.defaultBlockState());BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void slowRandomUpdatesAndFeatureGatesAreIndependent(GameTestHelper h){var p=caster(h,"bendalloy");var pos=p.blockPosition();var level=h.getLevel();boolean enabled=BubbleConfig.RANDOM_BLOCKS.get();try{level.setBlockAndUpdate(pos.below(),Blocks.SAND.defaultBlockState());level.setBlockAndUpdate(pos,Blocks.CACTUS.defaultBlockState());var reject=new net.minecraft.world.level.levelgen.LegacyRandomSource(1){@Override public double nextDouble(){return .9;}};level.getBlockState(pos).randomTick(level,pos,reject);h.assertTrue(level.getBlockState(pos).getValue(CactusBlock.AGE)==0,"A slowed random event can be deferred");BubbleConfig.RANDOM_BLOCKS.set(false);level.getBlockState(pos).randomTick(level,pos,reject);h.assertTrue(level.getBlockState(pos).getValue(CactusBlock.AGE)==1,"Disabling random-tick retiming restores native growth without disabling the bubble");}finally{BubbleConfig.RANDOM_BLOCKS.set(enabled);level.setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());level.setBlockAndUpdate(pos.below(),Blocks.AIR.defaultBlockState());BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void scheduledPrioritiesAndDuplicateProtectionSurviveRetiming(GameTestHelper h){var p=caster(h,"cadmium");var first=p.blockPosition();var second=first.offset(1,0,0);var queue=BubbleWorldGameTests.<Block>queue(h.getLevel(),first);if(!new ChunkPos(first).equals(new ChunkPos(second)))queue.addContainer(new ChunkPos(second),new LevelChunkTicks<>());long start=h.getLevel().getGameTime();var fired=new ArrayList<BlockPos>();try{put(queue,Blocks.STONE,first,start+4,TickPriority.NORMAL,0);put(queue,Blocks.STONE,first,start+4,TickPriority.NORMAL,0);put(queue,Blocks.STONE,second,start+4,TickPriority.EXTREMELY_HIGH,1);for(int i=1;i<=2;i++)BubbleWorldService.tickQueue(h.getLevel(),queue,start+i,100,(at,type)->fired.add(at));h.assertTrue(fired.equals(List.of(second,first)),"Duplicate ticks stay deduplicated and original priorities remain ordered");}finally{BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void outsideZeroDelayChainsAndDisabledFluidQueuesKeepNormalTime(GameTestHelper h){var p=caster(h,"cadmium");var inside=p.blockPosition();var outside=inside.offset(10,0,0);var queue=BubbleWorldGameTests.<Block>queue(h.getLevel(),outside);long start=h.getLevel().getGameTime();int[] count={0};boolean enabled=BubbleConfig.SCHEDULED_FLUIDS.get();try{put(queue,Blocks.STONE,outside,start+1,TickPriority.NORMAL,0);for(int frame=1;frame<=3;frame++){long now=start+frame;BubbleWorldService.tickQueue(h.getLevel(),queue,now,100,(at,type)->{count[0]++;put(queue,type,at,now,TickPriority.NORMAL,count[0]);});}h.assertTrue(count[0]==3,"Outside zero-delay chains run once per world frame, not once per local substep");BubbleConfig.SCHEDULED_FLUIDS.set(false);var fluid=BubbleWorldGameTests.<Fluid>queue(h.getLevel(),inside);int[] water={0};put(fluid,Fluids.WATER,inside,start+4,TickPriority.NORMAL,0);for(int frame=1;frame<=3;frame++)BubbleWorldService.tickQueue(h.getLevel(),fluid,start+frame,100,(at,type)->water[0]++);h.assertTrue(water[0]==0,"Disabled fluid retiming preserves its ordinary delay");BubbleWorldService.tickQueue(h.getLevel(),fluid,start+4,100,(at,type)->water[0]++);h.assertTrue(water[0]==1,"Fluid feature gate restores native queue timing independently");}finally{BubbleConfig.SCHEDULED_FLUIDS.set(enabled);BubbleService.clearPlayer(p);}h.succeed();}
    private BubbleWorldGameTests(){}
}
